rule('did-base','Past Simple','Did dan keyingi fe’l',new RegExp(`\\b(did(?:n${apost}t| not)?)(\\s+(?:I|you|he|she|it|we|they))?\\s+(${allVerbs})\\b`,'gi'),m=>m[1]+(m[2]||'')+' '+base(m[3]),'Did zamonni ko‘rsatadi. Undan keyin V2/V3 emas, fe’lning asosiy shakli keladi.',{guard:m=>base(m[3])!==m[3].toLowerCase(),priority:100});
rule('do-base',0,'Do/does dan keyingi fe’l',new RegExp(`\\b(do|does)(n${apost}t| not)?(\\s+(?:I|you|he|she|it|we|they))?\\s+(${allVerbs})\\b`,'gi'),m=>m[1]+(m[2]||'')+(m[3]||'')+' '+base(m[4]),'Do/does yordamchisidan keyin asosiy fe’lga s yoki ed qo‘shilmaydi.',{guard:m=>base(m[4])!==m[4].toLowerCase(),priority:100});
rule('modal-base',5,'Modaldan keyingi fe’l',new RegExp(`\\b(can|cannot|can${apost}t|could|couldn${apost}t|will|won${apost}t|would|wouldn${apost}t|should|shouldn${apost}t|must|mustn${apost}t|may|might)(\\s+not)?(\\s+(?:I|you|he|she|it|we|they))?\\s+(to\\s+)?(${allVerbs})\\b`,'gi'),m=>m[1]+(m[2]||'')+(m[3]||'')+' '+base(m[5]),'Can, will, should kabi modal fe’llardan keyin to siz asosiy shakl keladi. Ega he/she bo‘lsa ham s qo‘shilmaydi.',{guard:m=>!!m[4]||base(m[5])!==m[5].toLowerCase(),priority:110});
const uniquePast=alternatives(Object.entries(forms).filter(([,f])=>f[1]!==f[2]).map(([,f])=>f[1]));
rule('perfect-v3','Present Perfect','Have/has/had + V3',new RegExp(`\\b(have|has|had)\\s+(already\\s+|just\\s+|never\\s+|not\\s+)?(${uniquePast})\\b`,'gi'),m=>m[1]+' '+(m[2]||'')+forms[base(m[3])][2],'Perfect tuzilmasida have/has/had dan keyin uchinchi shakl kerak: went emas gone, saw emas seen.',{priority:95});
rule('perfect-be','Present Perfect','Been shakli',/\b(have|has|had)\s+(?:be|being)\s+(to|in|at|here|there|working|studying)\b/gi,m=>m[1]+' been '+m[2],'Perfect shaklida be ning V3 shakli been ishlatiladi.');
const unambiguousBases=alternatives(Object.keys(forms).filter(b=>!['be','have','do','read','come','run','put','cut','set','hit','hurt','cost'].includes(b)));
rule('third-person',0,'He/she/it bilan fe’l',new RegExp(`\\b(he|she|it)\\s+(${unambiguousBases})\\b`,'gi'),m=>m[1]+' '+forms[m[2].toLowerCase()][0],'Oddiy hozirgi zamon tasdiq gapida he/she/it bilan fe’lning s/es shakli kerak.',{guard:(m,t)=>!subjunctive(t,m.index)&&!pastCtx(t,m.index)&&! /\b(?:do|does|did|can|could|will|would|should|must|may|might|let|make|help)\s*$/i.test(clauseBefore(t,m.index)),priority:70});
const thirds=alternatives(Object.values(forms).map(f=>f[0]).filter(f=>!['is','has','does'].includes(f)));
rule('plural-base',0,'I/you/we/they bilan fe’l',new RegExp(`\\b(I|you|we|they)\\s+(${thirds})\\b`,'gi'),m=>m[1]+' '+base(m[2]),'I, you, we, they bilan oddiy hozirgi zamonda fe’lning s/es shakli ishlatilmaydi.');
rule('there-plural','There is / there are','There are',/\bthere\s+is\s+((?:two|three|four|five|six|seven|eight|nine|ten|many|several)\s+[a-z]+)\b/gi,m=>'there are '+m[1],'Ko‘plik narsa mavjudligini there are bilan aytamiz.',{priority:65});
rule('there-singular','There is / there are','There is',/\bthere\s+are\s+(an?\s+[a-z]+)\b(?!\s+of\b)/gi,m=>'there is '+m[1],'Birlikdagi a/an bilan boshlangan ot uchun there is kerak.',{guard:m=>!/^an?\s+(?:lot|few|couple|number|bunch|handful|variety|range|series|group|great|good|large|small|huge|wide|total|majority|minority|dozen|hundred|thousand|million|billion|pair|lots|bit|little)$/i.test(m[1])});
rule('these-plural','This, that, these, those','These/those + ko‘plik',/\b(these|those)\s+(book|student|car|house|child|person|dog|cat|question|problem|idea|day|year)\b/gi,m=>m[1]+' '+({child:'children',person:'people'}[m[2].toLowerCase()]||m[2]+'s'),'These va those ko‘plik ot bilan ishlatiladi.');
const plurals={childs:'children',childrens:'children',mans:'men',womans:'women',foots:'feet',tooths:'teeth',mouses:'mice',peoples:'people'};
rule('irregular-plural','Otlar va ko‘plik','Tartibsiz ko‘plik',new RegExp(`\\b(two|three|four|five|many|several|these|those)\\s+(${alternatives(Object.keys(plurals))})\\b`,'gi'),m=>m[1]+' '+plurals[m[2].toLowerCase()],'Bu otning ko‘plik shakli tartibsiz; oddiy s qo‘shish yetarli emas.');
rule('number-singular','Otlar va ko‘plik','Sondan keyingi ko‘plik',/\b(two|three|four|five|six|seven|eight|nine|ten|several|many)\s+(book|student|year|day|month|week|car|house|dog|cat|question|problem|idea|friend|person|child)\b/gi,m=>m[1]+' '+({person:'people',child:'children'}[m[2].toLowerCase()]||m[2]+'s'),'Birdan ortiq miqdordan keyin sanaladigan ot ko‘plikda bo‘ladi.',{guard:(m,t)=>!/^[-–]\w/.test(t.slice(m.index+m[0].length))});
rule('uncountable-plural','Sanaladigan va sanalmaydigan otlar','Sanalmaydigan ot',/\b(informations|advices|furnitures|homeworks|equipments|knowledges|luggages)\b/gi,m=>m[1].slice(0,-1),'Bu ma’nodagi ot odatda sanalmaydi va ko‘plik s olmaydi. Miqdor uchun piece/item kabi birlik kerak.');
rule('uncountable-article','Sanaladigan va sanalmaydigan otlar','Sanalmaydigan ot bilan a/an',/\b(an?)\s+(advice|information|furniture|homework|equipment|luggage)\b/gi,m=>'some '+m[2],'Bu ot odatda sanalmaydi. Umumiy miqdor uchun some; alohida birlik uchun a piece/item of ishlatish mumkin.');
rule('much-count','Some, any, no va miqdor','Much / many',/\b(much)\s+(books|students|people|cars|friends|questions|days|years|problems)\b/gi,m=>'many '+m[2],'Sanaladigan ko‘plik ot bilan many ishlatiladi.');
rule('many-mass','Some, any, no va miqdor','Many / much',/\b(many)\s+(water|money|time|information|advice|furniture|homework)\b/gi,m=>'much '+m[2],'Bu sanalmaydigan ma’noda much ishlatiladi.');
rule('every-plural','Each, every, both, either, neither','Every / each + birlik',/\b(every|each)\s+(students|books|persons|children|days|years|rooms)\b/gi,m=>m[1]+' '+({children:'child'}[m[2].toLowerCase()]||m[2].slice(0,-1)),'Every/each dan keyin to‘g‘ridan-to‘g‘ri kelgan ot odatda birlikda bo‘ladi.');
// Article pronunciation uses a curated lexicon. Unknown names/acronyms stay untouched.
const vowelWords='apple egg orange umbrella elephant idea example answer animal engineer artist actor interesting important excellent expensive old honest hour honor honour heir';
const consonantWords='book pen car dog cat student teacher doctor university uniform European useful user one year house happy good beautiful big small new young wonderful';
rule('article-an',4,'A yoki an',new RegExp(`\\ba\\s+(${alternatives(vowelWords.split(' '))})\\b`,'gi'),m=>'an '+m[1],'Bu so‘z unli tovush bilan boshlanadi; an kerak. Artikldan keyingi birinchi so‘zning tovushiga qarang.');
rule('article-a',4,'An yoki a',new RegExp(`\\ban\\s+(${alternatives(consonantWords.split(' '))})\\b`,'gi'),m=>'a '+m[1],'Bu so‘z undosh tovush bilan boshlanadi. University/useful boshida “yu”, one boshida “w” tovushi bor.');
rule('job-article',4,'Kasb oldidagi artikl',/\b(I am|he is|she is|I['’]m|he['’]s|she['’]s)\s+(teacher|doctor|student|engineer|artist|nurse|pilot|lawyer|programmer)\b/gi,m=>m[1]+(/^e|^a/i.test(m[2])?' an ':' a ')+m[2],'Birlikdagi sanaladigan kasb yoki maqom oldidan odatda a/an kerak.');
rule('double-comparative','Qiyosiy va orttirma daraja','Ikki marta qiyos',/\bmore\s+(better|worse|easier|harder|faster|slower|bigger|smaller|older|younger|cheaper|stronger)\b/gi,m=>m[1],'Qiyosiy shaklning o‘zi darajani bildiradi; more yana qo‘shilmaydi.');
rule('double-superlative','Qiyosiy va orttirma daraja','Ikki marta orttirma daraja',/\bmost\s+(best|worst|easiest|hardest|fastest|biggest|smallest|oldest|youngest)\b/gi,m=>m[1],'Superlative shakliga yana most qo‘shilmaydi.');
rule('than-then','Qiyosiy va orttirma daraja','Qiyosda than',/\b(better|worse|bigger|smaller|older|younger|faster|easier|taller|shorter)\s+then\b/gi,m=>m[1]+' than','Qiyoslashda than, vaqt ketma-ketligida then ishlatiladi.');
rule('enough-position','Too, enough, so, such','Enough ning o‘rni',/\benough\s+(tall|old|young|strong|fast|good|warm|big|small|rich|brave)\b/gi,m=>m[1]+' enough','Enough sifatdan keyin, otdan oldin keladi.',{guard:(m,t)=>!/^\s+[a-z]+/i.test(t.slice(m.index+m[0].length))});
rule('such-a','Too, enough, so, such','Such a/an',/\bsuch\s+(good|beautiful|interesting|wonderful|great)\s+(book|day|idea|story|person|place|film|movie)\b/gi,m=>'such '+(/^[aeiou]/i.test(m[1])?'an ':'a ')+m[1]+' '+m[2],'Such + sifat + birlik sanaladigan ot tuzilmasida a/an kerak.');
rule('weekday','Predloglar: in, on, at','Hafta kuni bilan on',/\b(?:in|at)\s+(Monday|Tuesday|Wednesday|Thursday|Friday|Saturday|Sunday)(s?)\b/gi,m=>'on '+m[1]+m[2],'Hafta kunlari bilan odatda on ishlatiladi.');
rule('month','Predloglar: in, on, at','Oy/yil bilan in',/\b(?:on|at)\s+(January|February|March|April|May|June|July|August|September|October|November|December)\b/gi,m=>'in '+m[1],'Oy nomi yolg‘iz kelganda odatda in. Aniq sanada on: on May 5.',{guard:(m,t)=>!/^\s+\d/.test(t.slice(m.index+m[0].length))});
rule('next-time','Predloglar: in, on, at','Next/last bilan predlog',/\b(?:in|on|at)\s+((?:next|last|this|every)\s+(?:week|month|year|Monday|Tuesday|Wednesday|Thursday|Friday|Saturday|Sunday))\b/gi,m=>m[1],'Next, last, this, every bilan bu vaqt ifodalarida odatda in/on/at kerak emas.');
const collocations=[['depend of','depend on'],['depends of','depends on'],['interested on','interested in'],['interested at','interested in'],['good in speaking','good at speaking'],['married with','married to'],['afraid from','afraid of'],['listen music','listen to music'],['listening music','listening to music'],['discuss about','discuss'],['discussed about','discussed'],['explain me','explain to me'],['arrive to school','arrive at school'],['arrived to school','arrived at school'],['informations about','information about']];
collocations.forEach(([bad,good],i)=>rule('collocation-'+i,'Bog‘liq predloglar va birikmalar','Predlog birikmasi',new RegExp('\\b'+esc(bad)+'\\b','gi'),()=>good,`Bu birikmada “${good}” shakli ishlatiladi. Predloglarni fe’l/sifat bilan birga o‘rganing.`,{priority:80}));
const gerunds=alternatives(['enjoy','enjoys','enjoyed','avoid','avoids','avoided','finish','finishes','finished','consider','considered','mind','suggest','suggested']);
rule('gerund-after','Gerund va infinitive','V-ing talab qiladigan fe’l',new RegExp(`\\b(${gerunds})\\s+to\\s+(${bases})\\b`,'gi'),m=>m[1]+' '+forms[m[2].toLowerCase()][3],'Enjoy, avoid, finish kabi fe’llardan keyin bu tuzilmada to V1 emas, V-ing keladi.',{guard:(m,t)=>!(/^(mind|minds)$/i.test(m[1])&&/\b(?:his|her|my|your|our|their|the|a|an|this|that|in|on|of|to|from|into|open|clear|whose)\s*$/i.test(clauseBefore(t,m.index)))&&!/\b(?:the|a|an|his|her|my|your|our|their|this|that)\s*$/i.test(clauseBefore(t,m.index))});
rule('infinitive-after','Gerund va infinitive','To-infinitive',new RegExp(`\\b(want|wants|wanted|decide|decides|decided|hope|hopes|hoped|plan|plans|planned)\\s+(${bases})\\b`,'gi'),m=>m[1]+' to '+m[2],'Want, decide, hope, plan dan keyingi fe’l bu tuzilmada to bilan keladi.');
rule('used-to-ing','Used to va be used to','Ko‘nikkanlik: V-ing',new RegExp(`\\b(am|is|are|was|were)\\s+used to\\s+(${unambiguousBases})\\b`,'gi'),m=>m[1]+' used to '+forms[m[2].toLowerCase()][3],'Be used to ko‘nikkanlikni bildiradi; to bu yerda predlog, undan keyingi fe’l V-ing bo‘ladi.');
rule('look-forward','Phrasal Verbs','Look forward to + V-ing',new RegExp(`\\b(look(?:s|ed|ing)? forward to)\\s+(${unambiguousBases})\\b`,'gi'),m=>m[1]+' '+forms[m[2].toLowerCase()][3],'Look forward to birikmasida to predlog bo‘lib, fe’l V-ing shaklida keladi.');
rule('suggest-person','Subjunctive va rasmiy tavsiyalar','Suggest tuzilmasi',/\b(suggest|suggested|suggests)\s+(me|him|her|us|them)\s+to\s+(\w+)\b/gi,m=>m[1]+' that '+({me:'I',him:'he',her:'she',us:'we',them:'they'}[m[2].toLowerCase()])+' '+m[3],'Suggest someone to do o‘rniga suggest that someone do yoki suggest doing ishlatiladi.');
rule('say-person','Reported Speech','Say va tell',/\b(said|say|says)\s+(me|him|her|us|them)\s+that\b/gi,m=>({said:'told',say:'tell',says:'tells'}[m[1].toLowerCase()])+' '+m[2]+' that','Odam bevosita ko‘rsatilganda tell someone that; say bilan say to someone ishlatiladi.');
rule('indirect-order','Bilvosita savollar va question tags','Bilvosita savol tartibi',/\b(Do you know|Could you tell me|Can you tell me|I wonder)\s+(where|why|when|how)\s+(is|are|was|were)\s+(he|she|it|you|we|they)\b/gi,m=>m[1]+' '+m[2]+' '+m[4]+' '+m[3],'Bilvosita savolning ichki qismida ega yordamchi fe’ldan oldin keladi.');
rule('relative-person','Relative Clauses','Odam uchun who',/\b(the man|the woman|the boy|the girl|the person)\s+which\s+(is|was|lives|works|called|helped)\b/gi,m=>m[1]+' who '+m[2],'Bu odamni aniqlayotgan gapda who ishlatiladi.');
const singularHeads='friend|brother|sister|mother|father|teacher|student|boy|girl|dog|cat';
const pluralHeads='friends|brothers|sisters|teachers|students|boys|girls|dogs|cats|children|people';
function directNounSubject(m,t){return !/\b(?:of|with|for|to|like|than|as|does|did|can|could|will|would|should|must|may|might|let|make|see|sees|saw|hear|hears|heard|watch|watched|feel|felt|notice|noticed|help|helped|have|has|had|get|gets|got|let|lets|want|wants|need|needs|ask|asks|asked|tell|tells|told|expect|expects|allow|allows|cause|causes|force|forces|require|requires|teach|teaches|encourage|persuade|invite|order|orders|and\s+(?:let|make|help))\s*$/i.test(clauseBefore(t,m.index))&&!subjunctive(t,m.index)}
rule('noun-third',0,'Birlik ega bilan fe’l',new RegExp(`\\b((?:my|your|his|her|our|their|the|a)\\s+(?:${singularHeads}))\\s+(${unambiguousBases})\\b`,'gi'),m=>m[1]+' '+forms[m[2].toLowerCase()][0],'Bu birlikdagi ega bilan oddiy hozirgi zamon fe’li s/es oladi.',{guard:(m,t)=>directNounSubject(m,t)&&!pastCtx(t,m.index)});
rule('noun-be-singular',3,'Birlik ega bilan is',new RegExp(`\\b((?:my|your|his|her|our|their|the|a)\\s+(?:${singularHeads}))\\s+are\\b`,'gi'),m=>m[1]+' is','Bu birlikdagi ega bilan is kerak.',{guard:(m,t)=>directNounSubject(m,t)&&!pastCtx(t,m.index)&&!/\band\s*$/i.test(t.slice(0,m.index))});
rule('noun-be-plural',3,'Ko‘plik ega bilan are',new RegExp(`\\b((?:my|your|his|her|our|their|the|these|those|two|three|many)\\s+(?:${pluralHeads}))\\s+is\\b`,'gi'),m=>m[1]+' are','Bu ko‘plikdagi ega bilan are kerak.',{guard:(m,t)=>directNounSubject(m,t)&&!pastCtx(t,m.index)});
rule('everyone-be','So‘z tartibi va ega–kesim mosligi','Birlikdagi umumiy olmosh',/\b(everyone|everybody|someone|somebody|anyone|anybody|nobody|no one)\s+are\b/gi,m=>m[1]+' is','Everyone/someone kabi olmoshlar standart yozuvda birlik fe’l oladi.');
rule('missing-be',3,'Yetishmayotgan be',/\b(I|he|she|we|they|you)\s+(very\s+)?(happy|sad|tired|hungry|thirsty|ready|busy|afraid)\b/gi,m=>m[1]+' '+({i:'am',he:'is',she:'is',we:'are',they:'are',you:'are'}[m[1].toLowerCase()])+' '+(m[2]||'')+m[3],'Holatni bildirgan bu gapda egadan keyin am/is/are kerak.',{guard:(m,t)=>! /\b(?:make|makes|made|find|found|keep|kept|want|wish|do|does|did|are|is|am|was|were|will|would|can|could|be)\s*$/i.test(clauseBefore(t,m.index))});
rule('continuous-base','Present Continuous','Be + V-ing',/\b(am|is|are)\s+(go|work|study|play|watch|sleep|run|swim|write|listen)\s+(to school|to work|at school|at home|in the park|English|football|TV|now|a letter|to music)\b/gi,m=>m[1]+' '+forms[m[2].toLowerCase()][3]+' '+m[3],'Davom etayotgan ishni be + V-ing bilan ifodalaymiz.',{priority:85});
rule('continuous-enjoy','Present Continuous','Be + enjoying',/\b(am|is|are)\s+enjoy\s+(reading|working|playing|learning|the trip|the film|the book)\b/gi,m=>m[1]+' enjoying '+m[2],'Bu davomiy shaklda enjoy emas, enjoying keladi.');
const frequency='always|usually|often|sometimes|never|rarely|also';
rule('third-person-adverb',0,'Ravishdan keyingi fe’l',new RegExp(`\\b(he|she|it)\\s+(${frequency})\\s+(${unambiguousBases})\\b`,'gi'),m=>m[1]+' '+m[2]+' '+forms[m[3].toLowerCase()][0],'Ravish ega–fe’l mosligini o‘zgartirmaydi: he/she/it bilan s/es kerak.',{guard:(m,t)=>!subjunctive(t,m.index)&&! /\b(?:do|does|did|can|could|will|would|should|must|may|might)\s*$/i.test(clauseBefore(t,m.index))});
rule('plural-adverb',0,'Ravishdan keyingi asosiy shakl',new RegExp(`\\b(I|you|we|they)\\s+(${frequency})\\s+(${thirds})\\b`,'gi'),m=>m[1]+' '+m[2]+' '+base(m[3]),'Bu ega bilan ravishdan keyin ham fe’lning asosiy shakli keladi.');
rule('aux-adverb',0,'Yordamchidan keyingi asosiy shakl',new RegExp(`\\b(do|does|did)(n${apost}t| not)?(\\s+(?:I|you|he|she|it|we|they))?\\s+(really|usually|always|often|ever|even)\\s+(${allVerbs})\\b`,'gi'),m=>m[1]+(m[2]||'')+(m[3]||'')+' '+m[4]+' '+base(m[5]),'Do/does/did va ravishdan keyin asosiy fe’l V1 shaklida keladi.',{guard:m=>base(m[5])!==m[5].toLowerCase(),priority:100});
rule('plural-noun-was','Past Simple','Ko‘plik ot bilan were',new RegExp(`\\b((?:my|your|his|her|our|their|the|these|those|two|three|many)\\s+(?:${pluralHeads}))\\s+was\\b`,'gi'),m=>m[1]+' were','Ko‘plikdagi bu ega bilan o‘tgan zamonda were ishlatiladi.',{guard:(m,t)=>directNounSubject(m,t)&&!pastCtx(t,m.index)});
rule('bare-plural-was','Past Simple','Ko‘plik ega bilan were',/\b(children|people|students|friends|dogs|cats)\s+was\b/gi,m=>m[1]+' were','Ko‘plikdagi bu ega bilan were kerak.',{guard:(m,t)=>! /\b(?:of|with|for|to)\s*$/i.test(clauseBefore(t,m.index))});
rule('missing-a-object',4,'Birlik ot oldidagi artikl',/\b(bought|buy|buys|have|has|need|needs|saw|see|sees)\s+(book|car|pen|laptop|bicycle|umbrella|apple)\b/gi,m=>m[1]+(/^[aeiou]/i.test(m[2])?' an ':' a ')+m[2],'Bu birlikdagi sanaladigan ot aniqlovchisiz kelgan. Yangi noma’lum narsa uchun a/an, ma’lum narsa uchun the yoki boshqa aniqlovchi kerak.');
rule('age-be',3,'Yoshni aytish',/\b(I have|he has|she has|they have|we have|you have)\s+(\d{1,2})\s+years old\b/gi,m=>m[1].replace(/have|has/i,v=>/^I\b/.test(m[1])?'am':/^(he|she)\b/i.test(m[1])?'is':'are')+' '+m[2]+' years old','Yosh inglizchada have bilan emas, be bilan aytiladi: I am 15 years old.');
rule('passive-v3','Passive Voice','Passive shaklida V3',/\b(was|were|is|are|been|be)\s+(wrote|stole|chose|gave|took|ate|spoke)\b/gi,m=>m[1]+' '+({wrote:'written',stole:'stolen',chose:'chosen',gave:'given',took:'taken',ate:'eaten',spoke:'spoken'}[m[2].toLowerCase()]),'Majhul nisbatda be dan keyin V3 kerak: was written, was taken.');
rule('past-participle-alone','Past Simple','Yordamchisiz V3',/\b(I|you|he|she|it|we|they)\s+(seen|written|eaten|spoken|driven|taken|given|known)\b/gi,m=>m[0],'Bu gapda V3 yolg‘iz turibdi. Tugagan voqea bo‘lsa V2; Perfect bo‘lsa have/has/had + V3 kerak. Ma’noga qarab tanlang.',{confidence:'medium'});
rule('cant-wont','Inkor gaplar','Qisqartmadagi apostrof',/\b(I|you|he|she|it|we|they)\s+(cant|wont)\s+(\w+)\b/gi,m=>m[1]+' '+(m[2].toLowerCase()==='cant'?"can't":"won't")+' '+m[3],'Can’t va won’t qisqartmalarida apostrof kerak.',{guard:m=>baseOf.has(m[3].toLowerCase()),priority:85});
