rule('tell-command-to','Reported Speech','Tell/ask dan keyingi to',new RegExp(`\\b(tell|tells|told|ask|asks|asked)\\s+(me|you|him|her|us|them)\\s+(${commandBases})(?=\\s+(?:my|your|his|her|our|their|the|a|an|this|that|home|here|there|now|tomorrow|today)|[.!?]|$)`,'gi'),m=>m[1]+' '+m[2]+' to '+m[3],'Buyruq yoki iltimosni yetkazishda tell/ask + odam + to V1 tuzilmasi kerak.');
