rule('missing-continuous-be','Present Continuous','V-ing oldidagi yordamchi',new RegExp(`\\b(I|you|he|she|we|they)\\s+(going|working|studying|playing|watching|sleeping|running|swimming|writing|cooking|dancing|reading)\\b`,'gi'),m=>m[1]+' '+({i:'am',he:'is',she:'is',we:'are',they:'are',you:'are'}[m[1].toLowerCase()])+' '+m[2],'Davomiy gapda am/is/are yordamchisi va V-ing birga keladi.',{guard:(m,t)=>! /\b(?:see|saw|seen|hear|heard|watch|watched|imagine|imagined|picture|pictured|like|liked|love|loved|hate|hated|mind|remember|remembered|find|found|catch|caught|want|about|with|without|are|is|am|was|were)\s*$/i.test(clauseBefore(t,m.index))});
