rule('direct-question-be','Savollar va yordamchi fe’llar','Savolda be ning o‘rni',/(^|[.!?]\s+)(Where|Why|When|How)\s+(I|you|he|she|we|they)\s+(am|is|are|was|were)([^.!?\n]{0,70})\?/gim,m=>{const past=/^(was|were)$/i.test(m[4]),singular=/^(I|he|she)$/i.test(m[3]);const be=past?(singular?'was':'were'):/^I$/i.test(m[3])?'am':/^(he|she)$/i.test(m[3])?'is':'are';return m[1]+m[2]+' '+be+' '+m[3]+m[5]+'?'},'To‘g‘ridan-to‘g‘ri be savolida am/is/are/was/were egadan oldin keladi va egaga moslanadi.',{priority:95});
