// Multi-token subjects and frequency phrases. Inflections come from the same lexicon.
const freqPhrase=`(?:(?:${frequency}|frequently|regularly|normally|seldom|really)\\s+){0,3}`;
const singularSubject=`(?:(?:my|your|his|her|our|their|the|a|an|this|that)\\s+(?:(?:young|old|new|good|best|little|big)\\s+){0,2}(?:${singularHeads}|doctor|nurse|child|person|school|company|government|student)|everyone|everybody|someone|somebody|nobody|each student)`;
