R('make-photo','Make va take',/\b(make|makes|made|making)\s+((?:a\s+|some\s+|the\s+)?(?:photos?|pictures?|selfies?|photographs?))\b/gi,m=>({make:'take',makes:'takes',made:'took',making:'taking'})[m[1].toLowerCase()]+' '+m[2],'Rasmga olish — take a photo/picture/selfie.',{priority:70,confidence:'medium'});
R('open-light','Open/close va turn on/off',/\b(open|opens|opened|opening|close|closes|closed|closing)\s+(the\s+)?(light|lights|tv|television|radio|computer|laptop|lamp|heater|air conditioner|internet|wifi|music)\b/gi,m=>({open:'turn on',opens:'turns on',opened:'turned on',opening:'turning on',close:'turn off',closes:'turns off',closed:'turned off',closing:'turning off'})[m[1].toLowerCase()]+' '+(m[2]||'')+m[3],'Elektr asboblarni yoqish/o‘chirish — turn on / turn off (open / close emas).',{priority:60,confidence:'medium'});
// missing "to" and extra "to"
const TOV='go|come|do|make|see|take|get|have|be|buy|play|eat|drink|learn|study|read|write|speak|meet|visit|travel|live|stay|leave|call|try|give|tell|ask|start|stop|join|find|know|say|think|become|cook|clean|swim|run|walk|drive|watch|listen|talk|finish|improve|pass|win|lose|marry|help|use|work|practice|practise|sleep|rest|start|begin|buy|sell|build|visit|send|bring|wear|move|change|win|prepare|explain|understand|remember|forget|become|show|follow|join|enjoy|choose|spend|save|earn|pay|answer|create|fix|open|close|wake|sit|stand|arrive|return|take|attend';
const TOV_SAFE=TOV.split('|').filter(v=>!['help','work','use','practice','practise','sleep','rest','change','answer','visit','call','play','cook','clean','open','close','start','show','return','move','talk','walk','run','drink','watch','swim','study','spend','save','pay','fix'].includes(v)).join('|');
R('missing-to-after-want','Infinitive: to',new RegExp(`\\b(want|wants|wanted|hope|hopes|hoped|decide|decides|decided|promise|promises|promised|manage|manages|managed|refuse|refuses|refused|afford|affords|afforded|expect|expects|expected|wish|wishes|wished|intend|intends|intended|attempt|attempts|attempted|deserve|deserves|deserved|tend|tends|tended|seem|seems|seemed|appear|appears|appeared|pretend|pretends|pretended|fail|fails|failed|agree|agrees|agreed|choose|chooses|chose|plan|plans|planned|would like|'d like|wouldn['’]t like|would love|'d love|learn|learns|learned)\\s+(${TOV_SAFE})\\b(?=\\s+(?:a|an|the|my|your|his|her|their|our|it|them|him|me|us|you|this|that|these|those|more|some|any|many|much|English|home|school|there|here|abroad|out|up|back|with|in|on|at|for|from|about|well|better|very|so|too|again|together|early|late|now|today|tomorrow|[A-Z][a-z]+|[a-z]+ing)\\b|\\s*[.!?,;]|\\s*$)`,'gi'),m=>m[1]+' to '+m[2],'Bu fe’ldan keyin to + V1 keladi: I want to go, I hope to see you, I’d like to learn.',{priority:93,guard:(m,t)=>!/\b(?:the|a|an|my|your|his|her|their|our|this|that|no|any|some|good|bad|new|old|big|small|first|second|last|next|real|only|final|main|great|best|better|worse)\s*$/i.test(clauseBefore(t,m.index))&&!(/^(plan|plans|expect|wish|hope|promise|fail|attempt|agree|choose|learn|seem|appear|tend)$/i.test(m[1])&&/^(?:be|have|do|make|get|take|go|see)$/i.test(m[2])&&/\b(?:the|a|an|my|your|his|her|their|our|this|that|no)\s*$/i.test(clauseBefore(t,m.index)))});
R('need-missing-to','Infinitive: to',new RegExp(`\\b(need|needs|needed)\\s+(${TOV_SAFE})\\b(?=\\s+(?:a|an|the|my|your|his|her|their|our|it|them|him|me|us|you|this|that|these|those|more|some|any|many|much|English|home|school|there|here|abroad|out|up|back|with|in|on|at|for|from|about|well|better|again|together|early|late|now|today|tomorrow|[a-z]+ing)\\b|\\s*[.!?,;]|\\s*$)`,'gi'),m=>m[1]+' to '+m[2],'Need dan keyin to + V1: I need to go. (Need + ot: I need help.)',{priority:93,confidence:'medium',guard:(m,t)=>/\b(?:I|you|we|they|he|she|it|who|that|which|just|really|also|still|always|never|don['’]t|doesn['’]t|didn['’]t|will|would|may|might|do|does|did)\s+(?:[a-z]+\s+)?$/i.test(t.slice(Math.max(0,m.index-18),m.index))});
R('ask-object-verb','Infinitive: to',new RegExp(`\\b(allow|allows|allowed|ask|asks|asked|tell|tells|told|expect|expects|expected|teach|teaches|taught|advise|advises|advised|invite|invites|invited|encourage|encourages|encouraged|force|forces|forced|enable|enables|enabled|remind|reminds|reminded|persuade|persuades|persuaded|warn|warns|warned|want|wants|wanted|need|needs|needed|would like|'d like|order|orders|ordered|require|requires|required)\\s+(me|him|her|us|them|you)\\s+(${TOV_SAFE})\\b(?!\\s+(?:to|ing)\\b)(?=\\s+(?:a|an|the|my|your|his|her|their|our|it|them|him|me|us|you|this|that|more|some|any|many|much|English|home|school|there|here|out|up|back|with|in|on|at|for|from|about|again|together|early|late|now|today|tomorrow|[a-z]+ing)\\b|\\s*[.!?,;]|\\s*$)`,'gi'),m=>m[1]+' '+m[2]+' to '+m[3],'Bu fe’l + kim + to + V1 tuzilmasini talab qiladi: I want you to come, She told me to wait.',{priority:93});
R('make-let-to','Infinitive: to',/\b(make|makes|made|let|lets)\s+(me|him|her|us|them|you|it)\s+to\s+([a-z]+)\b/gi,m=>m[1]+' '+m[2]+' '+m[3],'Make va let dan keyin to ishlatilmaydi: make him laugh, let me go.',{priority:93});
