const NOUN_END=(t,i)=>/^\s*(?:[.,!?;:)\]”"']|$|and\b|or\b|but\b|in\b|on\b|at\b|to\b|for\b|with\b|from\b|are\b|were\b|is\b|was\b|have\b|has\b|had\b|will\b|would\b|can\b|could\b|do\b|did\b|that\b|who\b|which\b|every\b|now\b|today\b|ago\b|there\b|here\b|of\b|by\b|as\b|than\b|when\b|because\b|so\b|too\b|yesterday\b|tomorrow\b|together\b|before\b|after\b|about\b|into\b|near\b)/i.test(t.slice(i));
const GR={tense:'Present Perfect',neg:'Inkor gaplar',q:'So‘roq gaplar',art:'Artikllar',pl:'Ko‘plik va sanaladigan otlar',cmp:'Taqqoslash darajalari',ind:'Ko‘chirma va ko‘chirma bo‘lmagan gaplar',cond:'Zero va First Conditional',mod:'Modal fe’llar',misc:'Boshqa grammatik xatolar'};
