const V3=bs=>forms[bs]?forms[bs][2]:bs, V2=bs=>forms[bs]?forms[bs][1]:bs, ING=bs=>forms[bs]?forms[bs][3]:bs+'ing';
const TIMEPAST='yesterday|last (?:night|week|month|year|summer|winter|spring|autumn|monday|tuesday|wednesday|thursday|friday|saturday|sunday|weekend|time)|\\d+ (?:days?|weeks?|months?|years?|hours?|minutes?) ago|a (?:day|week|month|year|moment|minute|while) ago|in (?:19|20)\\d\\d|(?:two|three|four|five|six|seven|ten) (?:days?|weeks?|months?|years?|hours?|minutes?) ago|when I was (?:a )?(?:child|kid|young|little|small)';
