G5('perfect-finished-time','Present Perfect va Past Simple',new RegExp(`\\b(I|you|we|they|he|she|it)\\s+(?:have|has|'ve|’ve)\\s+(?:not\\s+|never\\s+|already\\s+|just\\s+)?(\\w+)\\b([^.!?;\\n]{0,40}?)\\s+(${TIMEPAST})\\b`,'gi'),m=>{const b=baseOf.get(m[2].toLowerCase());return m[1]+' '+V2(b)+m[3]+' '+m[4]},'Aniq o‘tgan vaqt (yesterday, last year, two days ago) bilan Past Simple ishlatiladi, Present Perfect emas.',{topic:GR.tense,priority:99,guard:m=>{const b=baseOf.get(m[2].toLowerCase());return !!b&&forms[b]&&forms[b][2]===m[2].toLowerCase()&&!/^(been)$/i.test(m[2])||(m[2].toLowerCase()==='been'&&false)}});
G5('been-finished','Present Perfect va Past Simple',new RegExp(`\\b(I|you|we|they|he|she|it)\\s+(?:have|has)\\s+been\\s+(to|in|at)\\s+([A-Za-z ]{2,25}?)\\s+(${TIMEPAST})\\b`,'gi'),m=>m[1]+' '+({I:'was',you:'were',we:'were',they:'were',he:'was',she:'was',it:'was'}[m[1].replace(/^I$/,'I').toLowerCase()==='i'?'I':m[1].toLowerCase()])+' '+(m[2]==='to'?'in':m[2])+' '+m[3]+' '+m[4],'Aniq o‘tgan vaqt bilan Past Simple ishlatiladi: I was in Paris last year.',{topic:GR.tense,priority:99,confidence:'medium'});
